import { createHmac, timingSafeEqual } from 'node:crypto';
import { ApplicationError } from 'n8n-workflow';
import type { IDataObject } from 'n8n-workflow';
import { encodePath } from '../../shared/transport';
import type { HubWebhookRow, RequestSpec } from '../../shared/types';

/**
 * One Dutify service the trigger can subscribe to. `cfg` carries the selected `workspace` and the
 * source's own settings (for PM: `eventTypes`, `scopeType`, `scopeEntityIdentifier`).
 */
export interface WebhookSource {
	/** Registers `url`. `secret` is generated by the trigger and signs every delivery. */
	create(url: string, secret: string, cfg: IDataObject): RequestSpec;
	/** The id of the created webhook. The secret is the generated one: Dutify never returns it. */
	parseCreated(res: unknown, secret: string): { id: string; secret: string };
	/** The webhooks of `cfg.workspace`; a source may narrow the list to `cfg.url` on the server. */
	list(cfg: IDataObject): RequestSpec;
	/** The listed webhooks that deliver to `url`, in list order. */
	listAtUrl(res: unknown, url: string): ListedWebhook[];
	/**
	 * Re-registers `existing` (a webhook already at the trigger URL) with a new secret and the
	 * current settings, and switches it on, instead of creating another one.
	 */
	update(existing: ListedWebhook, secret: string, cfg: IDataObject): RequestSpec;
	remove(id: string, cfg: IDataObject): RequestSpec;
	/**
	 * Stops deliveries without deleting; used when the service refuses the delete (409). Absent
	 * when the service always deletes.
	 */
	deactivate?(id: string, cfg: IDataObject): RequestSpec;
	/** Lowercase, as n8n hands over request headers. */
	signatureHeader: string;
}

/** A webhook the service lists at the trigger URL. */
export interface ListedWebhook {
	id: string;
	/** The URL it delivers to (the trigger URL, since only those are listed). */
	url: string;
	/** False once paused (by the trigger, or by the service itself, e.g. after failed deliveries). */
	active: boolean;
	/** Whether it is narrowed to a space, folder, list or task. */
	scoped: boolean;
	createdAt?: string;
}

interface PmWebhookRow {
	identifier?: string;
	url?: string;
	active?: boolean;
	scopeType?: string | null;
	createdAt?: string;
}

const pmWebhooksPath = (cfg: IDataObject) =>
	encodePath`/mp/api/v1/workspaces/${String(cfg.workspace ?? '')}/webhooks`;

const pmWebhookPath = (id: string, cfg: IDataObject) =>
	`${pmWebhooksPath(cfg)}/${encodeURIComponent(id)}`;

/** PM webhook subscriptions (Webhook Resource). Deliveries carry `X-Webhook-Signature-256`. */
const pm: WebhookSource = {
	create(url, secret, cfg) {
		const body: IDataObject = { url, secret, name: 'n8n', eventTypes: cfg.eventTypes };
		if (cfg.scopeType) {
			body.scopeType = cfg.scopeType;
			body.scopeEntityIdentifier = cfg.scopeEntityIdentifier;
		}

		return { method: 'POST', path: pmWebhooksPath(cfg), body };
	},
	parseCreated(res, secret) {
		const id = (res as PmWebhookRow | null)?.identifier;
		if (!id) {
			throw new ApplicationError('Dutify did not return the ID of the created webhook');
		}

		return { id, secret };
	},
	list(cfg) {
		const spec: RequestSpec = { method: 'GET', path: pmWebhooksPath(cfg) };
		if (cfg.url) {
			// Exact-match filter; listAtUrl filters again for servers that ignore it.
			spec.qs = { url: String(cfg.url) };
		}

		return spec;
	},
	listAtUrl(res, url) {
		const rows = Array.isArray(res) ? (res as PmWebhookRow[]) : [];

		return rows
			.filter((row) => row.identifier && row.url === url)
			.map((row) => ({
				id: String(row.identifier),
				url,
				active: row.active !== false,
				scoped: Boolean(row.scopeType),
				createdAt: row.createdAt,
			}));
	},
	update(existing, secret, cfg) {
		// UpdateWebhookRequest: every field is optional; the URL stays as it is.
		const body: IDataObject = { secret, eventTypes: cfg.eventTypes, active: true };
		if (cfg.scopeType) {
			body.scopeType = cfg.scopeType;
			body.scopeEntityIdentifier = cfg.scopeEntityIdentifier;
		} else if (existing.scoped) {
			body.clearScope = true;
		}

		return { method: 'PUT', path: pmWebhookPath(existing.id, cfg), body };
	},
	remove(id, cfg) {
		return { method: 'DELETE', path: pmWebhookPath(id, cfg) };
	},
	deactivate(id, cfg) {
		// UpdateWebhookRequest: every field is optional, so this only switches the webhook off.
		return { method: 'PUT', path: pmWebhookPath(id, cfg), body: { active: false } };
	},
	signatureHeader: 'x-webhook-signature-256',
};

const HUB_HOOKS = '/api/user/webhooks';

const hubHookPath = (id: string) => `${HUB_HOOKS}/${encodeURIComponent(id)}`;

/** The UserWebhookDTO on/off flag. */
const switchedOn = (on: boolean): IDataObject => ({ enabled: on });

/**
 * Hub personal webhooks ("User Webhooks"), fired when a meeting finishes processing. A webhook
 * made through a key is bound to the key's workspace (the X-Dutify-Workspace header), so the
 * workspace travels in the header, not the path. Deliveries carry `X-Dutify-Signature`. Hub
 * deletes a webhook together with its log, so it needs no pause fallback.
 */
const meeting: WebhookSource = {
	create(url, secret, cfg) {
		return {
			method: 'POST',
			path: HUB_HOOKS,
			body: { url, secret, name: 'n8n', sections: cfg.sections },
		};
	},
	parseCreated(res, secret) {
		const id = (res as HubWebhookRow | null)?.id;
		if (id === undefined || id === null || id === '') {
			throw new ApplicationError('Dutify did not return the ID of the created webhook');
		}

		return { id: String(id), secret };
	},
	list() {
		return { method: 'GET', path: HUB_HOOKS };
	},
	listAtUrl(res, url) {
		const rows = Array.isArray(res) ? (res as HubWebhookRow[]) : [];

		return rows
			.filter((row) => row.id !== undefined && row.id !== null && row.url === url)
			.map((row) => ({
				id: String(row.id),
				url,
				active: row.enabled !== false,
				scoped: false,
			}));
	},
	update(existing, secret, cfg) {
		// Hub validates the URL on every update, so it is sent again.
		return {
			method: 'PUT',
			path: hubHookPath(existing.id),
			body: { url: existing.url, secret, sections: cfg.sections, ...switchedOn(true) },
		};
	},
	remove(id) {
		return { method: 'DELETE', path: hubHookPath(id) };
	},
	signatureHeader: 'x-dutify-signature',
};

/**
 * Sources by the value of the trigger's `source` property. PM is the webhook hub of the suite:
 * wiki (`codexum`) and feature-request (`roadmarq`) events are PM subscriptions too, with the
 * same endpoints and signature header, so those sources are the PM one.
 */
export const sources: Record<string, WebhookSource> = {
	pm,
	meeting,
	codexum: pm,
	roadmarq: pm,
};

const SIGNATURE_PREFIX = 'sha256=';

/**
 * Whether `header` is `sha256=` + the lowercase hex HMAC-SHA256 of the raw body keyed by `secret`.
 * The comparison is timing-safe.
 */
export function verifySignature(
	secret: string,
	rawBody: Buffer | undefined,
	header: string | undefined,
): boolean {
	if (!secret || !rawBody || typeof header !== 'string' || !header.startsWith(SIGNATURE_PREFIX)) {
		return false;
	}
	const expected = Buffer.from(
		SIGNATURE_PREFIX + createHmac('sha256', secret).update(rawBody).digest('hex'),
	);
	const actual = Buffer.from(header);

	return actual.length === expected.length && timingSafeEqual(actual, expected);
}
